INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65458650', 65458650, 'analyze_legacy', 'Provinsi DI Yogyakarta', 'provinsi', 'DINAS PEMBERDAYAAN MASYARAKAT, KALURAHAN, KEPENDUDUKAN DAN PENCATATAN SIPIL', 'Belanja Jasa Konsultansi Berorientasi Layanan-Jasa Khusus (Pendamping Penerapan Reformasi Pemberdayaan Masyarakat)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DI Yogyakarta, Yogyakarta (Kota)', 42000000, 'February 2026', 'APBD', 1, 1, '10 bulan', 'Reformasi Kalurahan sebagaimana dituangkan dalam Peraturan Gubernur Daerah Istimewa Yogyakarta Nomor 40 Tahun 2023 tentang Reformasi Kalurahan mengarahkan strategi pelaksanaannya ke dalam dua pendekatan, yaitu Reformasi Birokrasi Kalurahan dan Reformasi Pemberdayaan Masyarakat Kalurahan. Reformasi Pemberdayaan Masyarakat Kalurahan diarahkan pada upaya perbaikan dalam rangka mengembangkan kemandirian dan kesejahteraan masyarakat Kalurahan dengan meningkatkan pengetahuan, sikap, keterampilan, perilaku, kemampuan, kesadaran, serta memanfaatkan sumber daya melalui penetapan kebijakan, program, kegiatan dan pendampingan yang sesuai dengan esensi masalah dan prioritas kebutuhan masyarakat Kalurahan. Dalam mengatasi masalah hilir yang dirasakan langsung oleh masyarakat antara lain kondisi kemiskinan dan ketimpangan yang cukup tinggi antara kalurahan (perdesaan) dengan perkotaan di DIY, pendekatan Reformasi Pemberdayaan Masyarakat Kalurahan menjadi langkah strategis. Pengembangan kemandirian dan kesejahteraan masyarakat merupakan kunci upaya pemajuan Kalurahan yang salah satunya ditunjukkan oleh kemampuan masyarakat Kalurahan dalam melakukan pemberdayaan dan menyelesaikan masalah yang dihadapinya secara mandiri. Pelaksanaan Reformasi Pemberdayaan Masyarakat Kalurahan mempunyai sasaran, yaitu Meningkatnya Kemandirian dan Kesejahteraan Masyarakat Kalurahan.', 'a. Memberikan masukan, saran, ide / gagasan dan telaah baik secara lisan dan tertulis tentang Penerapan Reformasi Pemberdayaan Masyarakat Kalurahan; b. Mendampingi dalam Focus Group Discusion (FGD), diskusi, rapat koordinasi maupun komunikasi dengan pengampu kepentingan dalam rangka Penerapan Reformasi Pemberdayaan Masyarakat Kalurahan; c. Menyusun Laporan Penerapan Reformasi Pemberdayaan Masyarakat Kalurahan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2150021);
