INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65460033', 65460033, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pengadaan Pemeliharaan Instalasi Jaringan Untuk Pemenuhan Kegiatan Pemeliharaan Peralatan Perkantoran Pada Inspektorat jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 240000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1.0 PAKET', 'Melaksanakan pemeliharaan Instalasi Jaringan untuk Pemenuhan Kegiatan Pemeliharaan Peralatan Perkantoran pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026 sebanyak 1 (satu) paket selama 12 (dua belas) bulan yang meliputi pemeriksaan kondisi jaringan, pelaksanaan pemeliharaan preventif dan korektif, perbaikan atau penggantian komponen yang mengalami gangguan, penataan instalasi jaringan, pengujian fungsi jaringan setelah pemeliharaan, serta penyusunan laporan hasil pelaksanaan guna menjamin kelancaran dan keandalan operasional perkantoran.', 'Spesifikasi pekerjaan mencakup layanan pemeliharaan instalasi jaringan perkantoran yang dilaksanakan secara profesional, meliputi pemeriksaan kondisi jaringan secara berkala, penanganan gangguan teknis pada jaringan data dan komunikasi, perbaikan serta penyesuaian instalasi jaringan agar tetap berfungsi optimal, penataan ulang instalasi sesuai ketentuan teknis yang berlaku, pengujian kinerja jaringan pasca pemeliharaan, serta penyusunan laporan pelaksanaan pekerjaan sebagai bentuk pertanggungjawaban hasil pekerjaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2151568);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65459812', 65459812, 'analyze_legacy', 'Kementerian Luar Negeri', 'central', 'KEDUTAAN BESAR RI DI DAKAR', 'Konsumsi Kegiatan', 'Barang', 'Pengadaan Langsung', 'LAINNYA, Luar Indonesia', 4950000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 0, '( 20, ok, @ 15 )', '1. Konsumsi Kegiatan ( 20, ok, @ 15 );', '1. Konsumsi Kegiatan ( 20, ok, @ 15 );', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 0, 2151569);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65420311', 65420311, 'analyze_legacy', 'Pusat Pelaporan Dan Analisis Transaksi Keuangan', 'central', 'Pendidikan dan Pelatihan Anti Pencucian Uang PPATK', 'Pengadaan Pemeliharaan AC Split dan AC Standing pada Pusdiklat APUPPT TA 2026', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Depok (Kota)', 60000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 240, Unit, @ 250000 )', 'Pengadaan Pemeliharaan AC Split dan AC Standing pada Pusdiklat APUPPT TA 2026', 'Pemeliharaan AC Split dan AC Standing meliputi pembersihan unit indoor dan outdoor, pemeriksaan fungsi komponen mekanikal dan elektrikal, pengecekan tekanan gas refrigerant, serta pengurukuran arus listrik dan tekanan sistem. Kegiatan ini bertujuan untuk memastikan AC dapat beroperasi secara optimal, efisien, dan aman sesuai dengan kapasitas serta peruntukannya. SPESIFIKASI MUTU/KUALITAS a. Sebanyak 81 (delapan puluh satu) unit AC Split dan 2 (dua) unit AC Standing berfungsi normal dan menghasilkan udara dingin dengan baik. b. Seluruh komponen indoor dan outdoor dalam kondisi bersih dan layak operasional. c. Sistem pendinginan bekerja stabil tanpa kebocoran atau gangguan. d. Tekanan gas dan arus listrik berada dalam batas normal. e. Hasil pekerjaan dilengkapi laporan servis dan garansi pemeliharaan 1 (satu) bulan. SPESIFIKASI PEKERJAAN PEMELIHARAAN a. Pekerjaan Pembersihan • Pembersihan unit indoor dan outdoor AC, termasuk kumparan (coil) AC • Pembersihan dilakukan menggunakan peralatan dan metode yang sesuai agar tidak merusak komponen b. Pemeriksaan Komponen Indoor • Pemeriksaan fungsi cooling fan indoor • Pemeriksaan fungsi sistem elektrikal indoor c. Pemeriksaan Komponen Outdoor • Pemeriksaan fungsi kompresor AC • Pemeriksaan fungsi fan outdoor • Pemeriksaan tekanan gas refrigerant (freon) d. Pengukuran Teknis • Pemeriksaan dan pengukuran arus listrik (ampere) • Pemeriksaan dan pengukuran tekanan sistem (PSI) e. Pelaporan Pekerjaan • Penyusunan laporan tertulis hasil pemeliharaan dalam bentuk Form PMC-AC • Pengisian Service Card pada setiap unit AC yang dipelihara f. Garansi Pekerjaan • Penyedia memberikan garansi layanan pemeliharaan (PMC-AC) selama 1 (satu) bulan setelah pekerjaan selesai. Pekerjaan dilaksanakan 4 kali visit dalam 1 tahun. SPESIFIKASI AC SPLIT DAN AC STANDING No Uraian Perangkat AC Jml Satuan Qty 1 AC Split – 1 PK 4 Unit 4 visit/tahun 2 AC Split – 1,5 PK 64 Unit 4 visit/tahun 3 AC Split – 2 PK 10 Unit 4 visit/tahun 4 AC Standing – 3 PK 2 Unit 4 visit/tahun 5 AC Split – 5 PK 2 Unit 4 visit/tahun 6 AC Split - 10 PK 1 Unit 4 visit/tahun TENAGA TEKNIS Minimum 2 (dua) personel dengan pengalaman setidaknya 1 (satu) tahun dalam memelihara AC Split dan Standing PERALATAN No Nama Barang Jumlah Kondisi 1 Tang Amper 2 Buah Baik 2 Jet Pump Mesin Steam 2 Set Baik 3 Pompa Vakum 2 Unit Baik 4 Kunci Pas 2 Set Baik 5 Gauge Manifold 2 Buah Baik 6 Multi Tester 2 Buah Baik 7 Tangga Alumunium 2 Buah Baik 8 Termometer Digital 2 Buah Baik 9 Leak Detector 2 Buah Baik SPESIFIKASI WAKTU 11 Bulan dari Februari s/d 31 Desember 2026', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2151570);
