INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65460762', 65460762, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'PENGEMBANGAN KENAVIGASIAN PUSAT', 'Training Teknisi Telekomunikasi Pelayaran (TTP) Tk.III', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 1500000000, 'April 2026', 'APBN - PNBP (D)', 1, 1, '1 PAKET', 'Fungsi Direktorat Kenavigasian selain merencanakan serta membangun fasilitas tersebut adalah membangun Sumber Daya Manusia serta pemenuhan kompetensi di bidang teknis untuk terus ditingkatkan sehingga dapat berkontribusi dalam memberikan pelayanan operasional sesuai aturan Nasional maupu aturan internasional selama 24 jam 1 minggu dan 365 hari. Direktorat Kenavigasian saat ini mempunyai Stasiun Radio Pantai (SROP) sebanyak 154 lokasi diantaranya sebanyak 112 SROP telah dilengkapi sistim Global Maritime Distress Safey System (GMDSS). Sampai dengan tahun 2020 Direktorat Kenavigasian telah mendirikan 23 (dua puluh tiga) VTS di Indonesia . Untuk mendukung tetap beroperasinya peralatan tersebut perlu SDM berkualitas dan mengingat saat ini SDM di bidang Teknis masih jauh dari cukup serta banyaknya usulan permintaan dari UPT Disnav maka sangat perlu segera dididik untuk meningkatkan pengetahuan di bidang teknis serta memperoleh sertifikasi guna menunjang kinerja dan karirnya.', 'Dengan dilaksanakannya kegiatan Training Teknisi Telekomunikasi Pelayaran (TTP) TK. III Angkatan I Tahun 2026 ini maka tenaga teknis yang telah memiliki sertifikat tersebut diharapkan mampu untuk melakukan perawatan dan perbaikan perangkat Telekomunikasi Pelayaran sehingga dapat menunjang kinerja pelayanan Telekomunikasi Pelayaran baik itu VTS, Radio GMDSS maupun MEH agar lebih optimal. Kompetensi yang akan dicapai setelah mengikuti pelatihan ini diharapkan peserta mampu : 1. Mengenal fungsi radar, arsitektur perangkat keras radar, mengetahui ciri-ciri target, mengetahui dasar pemrosesan sinyal radar, mengetahui kinerja radardan gangguan, mampu melakukan identifikasi kerusakan pada sistem radar dan melakukan penggantian perangkat keras, mengetahui infrastruktur sistem radar; 2. Mengetahui cara kerja CCTV, menilai kinerja kamera CCTV,mengetahui karakteristik CCTV, merancang jaringan CCTV,melakukan instalasi dan perawatan sistem jaringan CCTV; 3. Mengetahui sistem komunikasi pada VTS, mengetahui dasar komunikasi radio VHF, mengetahui peralatan dan cara kerja komunikasi jarak jauh, mengetahui perangkat RDF, cara kerja dan perawatannya; 4. Mengetahui objektif dari AIS, memahami arsitektur perangkat keras AIS, mengetahui format dan data rate AIS, mampu melakukan perawatan terhadap perangkat AIS; 5. Mengetahui fungsi peralatan hydrometeo, memahami cara kerja perangkathydrometeo, mampu melakukan perawatan terhadap perangkat hydrometeo; 6. Mengetahui jaringan komputer dan server sebagai bagian dari VTS; mampu merancang, memasang, dan merawat jaringan komputer; mengoperasio nalkan dan merawat server VTS; 7. Memahamai terhadap pengetahuan dasar dan keterampilan untuk menangani pekerjaan baik yang sifatnya rutin maupun kontekstual di bidang teknik elektronika, meliputi pengujian, instalasi, operasi dan pemeliharaan; dan 8. Berwawasan yang luas mengenai perkembangan ilmu pengetahuan kontemporer sesuai dengan kompetensinya di bidang keterampilan teknik elektronika dan aspek-aspek yang terkait pada lingkup nasional maupun internasional. 1. Metode Pelaksanaan Pelaksanaan untuk kegiatan ini sesuai dengan Peraturan Menteri Keuangan Nomor 39 Tahun 2024 Tentang Standar Biaya Masukan (SBM) Tahun Anggaran 2025, oleh penyelenggara yang bekerja sama dengan Universitas/ Institut/ Sekolah Tinggi Negeri maupun Swasta dengan Narasumber/ Pengajar yang memliki Kompetensi padang bidang berikut: a. Ahli Teknik Elektro; b. Ahli Sistem Informasi dan Telekomunikasi; c. Ahli IT, dll 2. Tahapan dan Waktu Pelaksanaan a. Penyampaian permintaan calon peserta kepada UPT terkait b. Penetapan Calon Peserta c. Pelaksanaan Kegiatan d. Evaluasi', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2152928);
