INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65421685', 65421685, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'KELURAHAN BUKIT DURI - JAKSEL', 'Belanja Jasa Tenaga Penanganan Prasarana dan Sarana Umum (Gaji PPSU)', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 2876473613, 'December 2025', 'APBD', 1, 1, '47 orang x 13 bulan', 'Ruang Lingkup Pekerjaan 1. Penanganan prasarana dan sarana jalan untuk : - Perbaikan jalan berlubang di wilayah kelurahan - Perbaikan dan pengecatan kanstin, perbaikan pembatas jalan yang rusak di wilayah kelurahan - Perbaikan trotoar jalan yang rusak dan/atau berlubang di wilayah kelurahan 2. Penanganan prasarana dan sarana saluran untuk : - Perbaikan saluran rusak di jalan lingkungan/lokal - Pengurasan saluran, tali-tali dan mulut-mulut air yang mampet di jalan lingkungan/lokal - Pelaporan segera pembangunan atau aktifitas yang berpotensi menggangu saluran termasuk penutupan saluran air kepada Satuan Kerja Perangkat Daerah (SKPD) terkait melalui lurah 3. Penanganan prasarana dan sarana taman untuk: - Pohon Tumbang dan/atau patah di wilayah kelurahan - Pemangkasan ranting pohon yang menutupi rambu lalulintas, lampu jalan dan yang membahayakan keselamatan di wilayah kelurahan - Pembabatan rumput dan semak liar di wilayah kelurahan - Pengambilan pot-pot rusak yang menggangu lingkungan - Pelaporan segera penebangan pohon pelindung tanpa izin kepada Satuan Kerja Perangkat Daerah (SKPD) terkait melalui lurah. 4. Penanganan prasarana dan sarana kebersihan untuk: - Pembersihan timbunan sampah liar dan ceceran sampah di wilayah kelurahan - Pembersihan coret-coretan dan keeping informasi di ruang public wilayah kelurahan - Pembersihan jalan, saluran, taman, bangunan dan/atau ruang public lainnya di wilayah Kelurahan 5. Penanganan prasarana dan sarana penerangan jalan umum untuk: - Penanganan penerangan jalan umum yang rusak dan/atau membahayakan keselamatan - Penanganan sementara lampu jalan yang rusak/mati dengan menggunakan lampu jalan sementara untuk menerangi jalan sesuai dengan kebutuhan - Pelaporan jaringan utilitas yang menganggu kepentingan umum di jalan lingkungan/lokal - Pelaporan lampu penerangan jalan yang dibutuhkan warga dan yang tidak berfungsi. 6. Penanganan kebersihan pasca banjir', '1. Warga Negara Indonesia ; 2. Diutamakan memiliki Kartu Tanda Penduduk (KTP) Provinsi DKI Jakarta ; 3. Berusia paling rendah 18 Tahun 0 Bulan 0 Hari dan Paling tinggi 56 Tahun 0 Bulan 0 Hari pada tanggal 31 Desember 2025; 4. Ijazah minimal SD atau dapat membaca dan menulis dalam bahasa Indonesia ; dibutuhkan sebanyak 47 orang', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2153295);
