INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65462221', 65462221, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'PENGEMBANGAN KENAVIGASIAN PUSAT', 'Training Operator VTS sesuai IALA Model Courses C103-1', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 1120000000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 PAKET', 'Sesuai dengan Kep Menpan RB Republik Indonesia tentang Nomenklatur Jabatan Pelaksana Pegawai Negeri Sipil di Lingkungan Instansi Pemerintah, telah diatur Jabatan Pelaksana untuk Manager, Supervisor , Operator dan Teknisi Vessel Traffic Services VTS sesuai dengan kualifikasi dan sertifikat keterampilannya. Memperhatikan kondisi sumber daya manusia Operator VTS pada Stasiun VTS Ditjen Hubla yang sudah beroperasi di wilayah Indonesia, sampai dengan saat ini masih banyak personil di masing-masing stasiun VTS yang belum memiliki kompetensi yang cukup, dalam hal ini perlu training bagi Operator VTS harus sesuai dengan standar yang termuat dalam aturan Internasional oleh International Association of Marine Aids to Navigation and Lighthouse Authorities (IALA) sesuai Model Courses Vessel Traffic Service Operators Training C103-1.', 'Sesuai dengan Keputusan Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi Republik Indonesia tentang Nomenklatur Jabatan Pelaksana Pegawai Negeri Sipil di Lingkungan Instansi Pemerintah, telah diatur Jabatan Pelaksana untuk Manager, Supervisor , Operator dan Teknisi Vessel Traffic Services VTS sesuai dengan kualifikasi dan sertifikat keterampilannya. Memperhatikan kondisi sumber daya manusia Operator VTS pada Stasiun VTS Ditjen Hubla yang sudah beroperasi di wilayah Indonesia, sampai dengan saat ini masih banyak personil di masing-masing stasiun VTS yang belum memiliki kompetensi yang cukup, dalam hal ini perlu training bagi Operator VTS harus sesuai dengan standar yang termuat dalam aturan Internasional oleh International Association of Marine Aids to Navigation and Lighthouse Authorities (IALA) sesuai Model Courses Vessel Traffic Service Operators Training C103-1. Maka perlu segera diberikan kesempatan bagi para Operator VTS untuk mengikuti kegiatan Training Operator VTS sesuai aturan dimaksud guna memberikan pelayanan jasa Telekomunikasi Pelayaran dengan standar internasional untuk meningkatkan keselamatan dan keamnan pelayaran dan perlindungan lingkungan laut khususnya di perairan Indonesia. Maksud dan Tujuan Adapun maksud dan tujuan dari Training Operator Vessel Traffic Services (VTS) Sesuai IALA Model Courses C103-1 For Operators adalah Pemenuhan kompetensi Operator VTS Ditjen Hubla dalam memperoleh sertifikat kompetensi untuk pemenuhan Keputusan Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi Republik Indonesia tentang Nomenklatur Jabatan Pelaksana Pegawai Negeri Sipil di Lingkungan Instansi Pemerintah, telah diatur Jabatan Pelaksana untuk Manager, Supervisor , Operator dan Teknisi Vessel Traffic Services VTS sesuai dengan kualifikasi dan sertifikat keterampilannya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2154877);
