INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65461811', 65461811, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL KEKAYAAN INTELEKTUAL', 'Pengadaan Perangkat Keamanan WAN Pada Direktorat Teknologi Informasi Direktorat Jenderal Kekayaan Intelektual Tahun Anggaran 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 4662000000, 'March 2026', 'APBN - PNBP (D)', 1, 0, '2 Paket', 'Menyediakan perangkat, instalasi dan Konfigurasi dan instalasi perangkat baru dengan tujuan terhubung dengan jaringan eksisting, memberikan Layanan SLA untuk ketersediaan barang yang akan diberikan bila terjadi kerusakan 8x5x Next Business Day/Return merchandise authorization (RMA)', '- Memiliki pusat riset dan respons ancaman global dengan monitoring dan respons 24x7. - Mendukung high availability (active-active, active-passive, atau clustering) dengan catu daya redundan. - Perangkat 1U rackmount dengan port manajemen, HA, Ethernet tembaga & fiber (1G/10G/25G), console, dan USB. - Storage SSD redundan dan dual power supply. - Mendukung transceiver 1G, 10G, dan 25G. - Performa tinggi untuk NGFW, IPS, Threat Protection, Application Control, dan SSL Inspection (kelas enterprise). - Mendukung kapasitas sesi besar (jutaan concurrent session) dan high new session rate. - Mendukung ribuan koneksi SSL VPN dengan latensi rendah. - Fitur keamanan lengkap: Firewall, IPS, Application Control, Antivirus/Anti-Malware, Anti-Botnet, Web & Video Filtering, Antispam. - Mendukung SSL/HTTPS inspection, kebijakan IPv4/IPv6, NAT terpusat, mode routed & transparent. - Mendukung dynamic routing (BGP, OSPF, RIP), QoS/traffic shaping, serta virtual domain (multi-tenant). - Mendukung IPSec VPN (site-to-site & remote access) dan SSL VPN tanpa lisensi tambahan. - Mendukung custom signature, dynamic blocklist eksternal, serta proteksi credential/phishing. - Manajemen berbasis Web GUI (HTTPS) tanpa software tambahan. - Mendukung upgrade firmware dengan rollback. - Autentikasi admin melalui LDAP/RADIUS, monitoring ancaman real-time, dan update signature otomatis. - Mendukung logging & notifikasi via email, syslog, dan SNMP. - Termasuk subscription security lengkap 1 tahun, premium support, software update, dan Advanced Hardware Replacement (NBD). - Dukungan teknis 24x7.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2155057);
