INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65502859', 65502859, 'analyze_legacy', 'Kab. Tulungagung', 'kabkota', 'UPTD PUSKESMAS REJOTANGAN', '5.1.02.01.01.0052  Belanja Makanan dan Minuman Rapat', 'Barang', 'Pengadaan Langsung', 'Jawa Timur, Tulungagung (Kab.)', 15700000, 'January 2026', 'BLUD', 1, 1, '1 paket', '- Snack (Prolanis) - Belanja Snack lokakarya mini tribulanan lintas sektor - Belanja Nasi lokakarya mini tribulanan lintas sektor', '1 x 704 kotak 12.500 8.800.000,00 4 x 30 kotak 20.000 2.400.000,00 4 x 30 kotak 37.500 4.500.000,00', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2156171);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65463836', 65463836, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'PENGEMBANGAN KENAVIGASIAN PUSAT', 'Refresher Operator SROP dan VTS', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Bekasi (Kota)', 200000000, 'April 2026', 'APBN - PNBP (D)', 1, 1, '1 PAKET', 'IMO telah menetapkan aturan mengenai keselamatan dan keamanan pelayaran dalam Safety of Life at Sea (SOLAS) Chapter V yg mengatur keselamatan pelayaran untuk semua kapal-kapal. Oleh karena itu, dibuatlah suatu sistem yaitu Vessel Traffic Services (VTS) di wilayah pelabuhan, selat dan remote site. Indonesia telah diakui sebagai negara kepulauan oleh United Nation Convention of the Law of the Sea (UNCLOS). Melalui pengakuan tsb, Indonesia telah diberikan hak dan tanggung jawab untuk memantau lalu lintas pelayaran di wilayah perairan teritorialnya. Salah satu faktor utama dalam menunjang kelancaran transpotasi laut adalah tersedianya sarana telekomunikasi pelayaran dan perlu dilakukan peningkatan kompetensi bagi para operator vts/srop untuk memastikan operator dapat melaksanakan tugas dan fungsi dari VTS/SROP dgn baik dan bertanggung jwb.', 'STRATEGI PENCAPAIAN KELUARAN 1. Metode Pelaksanaan Adapun metode pelaksanaan adalah Biaya Perjalanan Dinas yang menggunakan sistem at cost dengan biaya yang dikeluarkan tidak lebih dari Peraturan Menteri Keuangan Nomor 39 Tahun 2024 Tentang Standar Biaya Masukan (SBM) Tahun Anggaran 2025. 2. Tahapan dan Waktu Pelaksanaan adalah sebagai berikut: a. Penyampaian permintaan calon peserta kepada UPT terkait; b. Melaksanaan kegiatan; c. Laporan hasil kegiatan. Adapun penerima manfaat Refresher Operator Stasiun Radio Pantai (Srop) dan Vessel Traffic Services (VTS) adalah: 1. Operator Telemunikasi Pelayaran dapat bertukar pikiran/pengetahuan dan permasalahan untuk dapat dicarikan solusi secara cepat dan akurat. 2. Operator Telemunikasi Pelayaran dapat mengetahui perkembangan Teknologi Informasi dan sekaligus operasional untuk menjalankan tugas dan pelaksanaan Keselamatan Pelayaran. 3. Operator Telekomunikasi Pelayaran dapat menjalankan operasional sesuai Prosedur dan Evaluasi sesuai SOP evaluasi terhadap pelaksanaan Layanan Informasi untuk Pengguna atau masyarakat pelayaran.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2156172);
