INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65464240', 65464240, 'analyze_legacy', 'Provinsi DI Yogyakarta', 'provinsi', 'DINAS PEMBERDAYAAN MASYARAKAT, KALURAHAN, KEPENDUDUKAN DAN PENCATATAN SIPIL', 'Belanja Jasa Konsultansi Berorientasi Layanan-Jasa Khusus (Penguatan Kelembagaan Ekonomi Kalurahan)', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DI Yogyakarta, Yogyakarta (Kota)', 37800000, 'November 2026', 'APBD', 1, 1, '3 bulan', 'Penguatan kegiatan pemberdayaan perekonomian merupakan upaya yang dilakukan dalam rangka meningkatkan keberdayaan perekonomian kalurahan melalui optimalisasi Badan Usaha Milik Kalurahan (BUMKal) sebagai penggerak utama perekonomian kalurahan. Undang-Undang Nomor 11 Tahun 2020 tentang Cipta Kerja telah menegaskan kedudukan BUM Desa sebagai badan hukum yang didirikan oleh Desa dan/ atau bersama Desa-Desa guna mengelola usaha, memanfaatkan aset, mengembangkan investasi dan produktivitas, menyediakan jasa pelayanan, dan/ atau menyediakan jenis usaha lainnya untuk sebesar-besarnya kesejahteraan masyarakat Desa. Keberadaan gotong royong telah mengakar kuat sebagai kekayaan intelektual bangsa. Gotong royong telah menjadi ciri khas bangsa dan potensi yang berkelanjutan, bernilai, dan identik dengan kemandirian. Program Global Gotong Royong (G2R) Tetrapreneur adalah inovasi solidaritas gerakan gotong royong dan wirausaha desa yang bertujuan membawa kearifan lokal Indonesia ke kancah dunia. Sasaran G2R adalah pedesaan, yang notabene adalah salah satu wilayah yang memiliki keunggulan bersaing yang terintegrasi baik melalui pemerintah, akademisi, pemerintah desa maupun lembaga-lembaga yang berada di dalam desa hingga masyarakat luas.', 'a. Memberikan masukan, saran, ide / gagasan dan telaah baik secara lisan dan tertulis tentang Penguatan Ekonomi Kalurahan; b. Mendampingi dalam Focus Group Discusion (FGD), diskusi, rapat koordinasi maupun komunikasi dengan pengampu kepentingan dalam rangka Penguatan Ekonomi Kalurahan; c. Menyusun Laporan PPenguatan Ekonomi Kalurahan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2158580);
