INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65465346', 65465346, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'KONSULTAN JUNIOR PENYUSUNAN KAJIAN PEMETAAN RISIKO DAN POTENSI USAHA KOPERAS DESA/KELURAHAN MERAH PUTIH WILAYAH BARAT', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99900000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '11 Bulan', '1. Menyusun katalog kegiatan usaha KDKMP (6 kelompok usaha) untuk wilayah Barat Indonesia (Pulau Sumatera, Pulau Jawa, dan Pulau Kalimantan) sebagai instrumen pemetaan risiko dan kesiapan pelaksanaan kebijakan, termasuk dengan pemanfaatan kecerdasan artifisial sebagai alat bantu pengolahan dan analisis data kuantitatif. 2. Menyusun executive report Manajemen Risiko Pembangunan Nasional (MRPN) KDKMP yang memuat executive summary, profil indikatif risiko pelaksanaan, serta alternatif mitigasi; 3. Memberikan dukungan analitis dalam pemetaan risiko pelaksanaan dan potensi kegiatan usaha KDKMP di wilayah Barat Indonesia sebagai bahan penajaman kebijakan pengembangan KDKMP; serta 4. Menyusun laporan analitis bulanan mengenai perkembangan kebijakan, profil risiko, isu strategis, dan tindak lanjut pengendalian risiko pelaksanaan KDKMP.', '1. Menyusun katalog kegiatan usaha KDKMP (6 kelompok usaha) untuk wilayah Barat Indonesia (Pulau Sumatera, Pulau Jawa, dan Pulau Kalimantan) sebagai instrumen pemetaan risiko dan kesiapan pelaksanaan kebijakan, termasuk dengan pemanfaatan kecerdasan artifisial sebagai alat bantu pengolahan dan analisis data kuantitatif. 2. Menyusun executive report Manajemen Risiko Pembangunan Nasional (MRPN) KDKMP yang memuat executive summary, profil indikatif risiko pelaksanaan, serta alternatif mitigasi; 3. Memberikan dukungan analitis dalam pemetaan risiko pelaksanaan dan potensi kegiatan usaha KDKMP di wilayah Barat Indonesia sebagai bahan penajaman kebijakan pengembangan KDKMP; serta 4. Menyusun laporan analitis bulanan mengenai perkembangan kebijakan, profil risiko, isu strategis, dan tindak lanjut pengendalian risiko pelaksanaan KDKMP.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2159551);
