INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65466385', 65466385, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'BANDAR UDARA JUWATA DI TARAKAN', 'Pemeliharaan Printer dan Scanner', 'Jasa Lainnya', 'Dikecualikan', 'Kalimantan Utara, Tarakan (Kota)', 48000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, PAKET, @ 48000000)', '1. Pemeliharaan Printer dan Scanner ( 1, PAKET, @ 48000000);', 'Kegiatan pemeliharaan printer dan scanner dilaksanakan untuk menjaga keandalan dan kelancaran perangkat pendukung administrasi perkantoran dalam proses pencetakan dan digitalisasi dokumen. Kegiatan ini meliputi identifikasi kebutuhan pemeliharaan, pembersihan dan perawatan rutin, penggantian komponen atau suku cadang yang mengalami keausan, pengisian ulang tinta/toner, kalibrasi perangkat, serta penanganan gangguan teknis. Selain itu dilakukan pemeriksaan fungsi dan dokumentasi hasil pemeliharaan guna memastikan perangkat dapat beroperasi secara optimal. Dengan terlaksananya pemeliharaan printer dan scanner secara berkala, diharapkan proses administrasi, pengarsipan, dan pelayanan dokumen dapat berjalan efektif, efisien, dan tepat waktu', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2159613);
