INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65464149', 65464149, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'PENGEMBANGAN KENAVIGASIAN PUSAT', 'Refresher Operator SROP dan VTS', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Bekasi (Kota)', 200000000, 'April 2026', 'APBN - PNBP (D)', 1, 1, '1 PAKET', 'IMO telah menetapkan aturan mengenai keselamatan dan keamanan pelayaran dalam Safety of Life at Sea (SOLAS) Chapter V yg mengatur keselamatan pelayaran untuk semua kapal-kapal. Oleh karena itu, dibuatlah suatu sistem yaitu Vessel Traffic Services (VTS) di wilayah pelabuhan, selat dan remote site. Indonesia telah diakui sebagai negara kepulauan oleh United Nation Convention of the Law of the Sea (UNCLOS). Melalui pengakuan tsb, Indonesia telah diberikan hak dan tanggung jawab untuk memantau lalu lintas pelayaran di wilayah perairan teritorialnya. Salah satu faktor utama dalam menunjang kelancaran transpotasi laut adalah tersedianya sarana telekomunikasi pelayaran dan perlu dilakukan peningkatan kompetensi bagi para operator vts/srop untuk memastikan operator dapat melaksanakan tugas dan fungsi dari VTS/SROP dgn baik dan bertanggung jwb.', 'STRATEGI PENCAPAIAN KELUARAN 1. Metode Pelaksanaan Adapun metode pelaksanaan adalah Biaya Perjalanan Dinas yang menggunakan sistem at cost dengan biaya yang dikeluarkan tidak lebih dari Peraturan Menteri Keuangan Nomor 39 Tahun 2024 Tentang Standar Biaya Masukan (SBM) Tahun Anggaran 2025. 2. Tahapan dan Waktu Pelaksanaan adalah sebagai berikut: a. Penyampaian permintaan calon peserta kepada UPT terkait; b. Melaksanaan kegiatan; c. Laporan hasil kegiatan. Adapun penerima manfaat Refresher Operator Stasiun Radio Pantai (Srop) dan Vessel Traffic Services (VTS) adalah: 1. Operator Telemunikasi Pelayaran dapat bertukar pikiran/pengetahuan dan permasalahan untuk dapat dicarikan solusi secara cepat dan akurat. 2. Operator Telemunikasi Pelayaran dapat mengetahui perkembangan Teknologi Informasi dan sekaligus operasional untuk menjalankan tugas dan pelaksanaan Keselamatan Pelayaran. 3. Operator Telekomunikasi Pelayaran dapat menjalankan operasional sesuai Prosedur dan Evaluasi sesuai SOP evaluasi terhadap pelaksanaan Layanan Informasi untuk Pengguna atau masyarakat pelayaran.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2159992);
